-- Additive documents and policies on the established stock, supplier and journal engines.
CREATE TABLE IF NOT EXISTS pink_pack_receiving_policies(business_unit_id INTEGER PRIMARY KEY REFERENCES business_units(id),grni_account_id INTEGER NOT NULL REFERENCES accounting_accounts(id),policy_reference TEXT NOT NULL,approved_by INTEGER NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pink_pack_revisions(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL,purchase_id INTEGER NOT NULL REFERENCES pink_pack_purchases(id),kind TEXT NOT NULL,reason TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pink_pack_credits(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL,purchase_id INTEGER NOT NULL REFERENCES pink_pack_purchases(id),receipt_line_id INTEGER REFERENCES pink_pack_receipt_lines(id),credit_reference TEXT NOT NULL,credit_date TEXT NOT NULL,quantity REAL NOT NULL DEFAULT 0,amount REAL NOT NULL,amount_krw REAL NOT NULL,clearing_krw REAL NOT NULL DEFAULT 0,reason TEXT NOT NULL,journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(purchase_id,credit_reference));
CREATE TABLE IF NOT EXISTS pink_pack_reservations(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL,reference TEXT NOT NULL,outputs_json TEXT NOT NULL,bom_json TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Reserved',batch_id INTEGER REFERENCES pink_salt_production_batches(id),created_by INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(business_unit_id,reference));
CREATE TABLE IF NOT EXISTS pink_pack_reservation_lines(reservation_id INTEGER NOT NULL REFERENCES pink_pack_reservations(id),material_id INTEGER NOT NULL REFERENCES pink_salt_packaging_items(id),location_id INTEGER REFERENCES pink_salt_storage_locations(id),quantity REAL NOT NULL CHECK(quantity>0),PRIMARY KEY(reservation_id,material_id,location_id));
CREATE TABLE IF NOT EXISTS pink_pack_production_returns(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL,batch_id INTEGER NOT NULL REFERENCES pink_salt_production_batches(id),material_id INTEGER NOT NULL REFERENCES pink_salt_packaging_items(id),quantity REAL NOT NULL,reason TEXT NOT NULL,movement_date TEXT NOT NULL,journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_pack_reserved_active ON pink_pack_reservations(business_unit_id,status,id);
CREATE TABLE IF NOT EXISTS pink_pack_finished_cost_adjustments(id INTEGER PRIMARY KEY,return_id INTEGER NOT NULL REFERENCES pink_pack_production_returns(id),batch_id INTEGER NOT NULL,product_id INTEGER NOT NULL,amount_krw REAL NOT NULL,UNIQUE(return_id,product_id));
CREATE TABLE IF NOT EXISTS pink_pack_external_costs(id INTEGER PRIMARY KEY,business_unit_id INTEGER NOT NULL,purchase_id INTEGER NOT NULL REFERENCES pink_pack_purchases(id),supplier_id INTEGER NOT NULL REFERENCES pink_salt_suppliers(id),invoice_reference TEXT NOT NULL,cost_date TEXT NOT NULL,currency TEXT NOT NULL,amount REAL NOT NULL,recognition_rate REAL NOT NULL,amount_krw REAL NOT NULL,treatment TEXT NOT NULL,reason TEXT NOT NULL,journal_id INTEGER REFERENCES accounting_journal_entries(id),created_by INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(supplier_id,invoice_reference));
